mapper.select:
select PORTFOLIO_ID portfolioId, /*组合代码*/ PORTFOLIO_NAME portfolioName, /*产品名称*/ profitType, FINPROD_ID finprodId,/*产品代码*/ FINPROD_MARKET_ID prodId,/*理财产品代码*/ FINPROD_ABBR finprodAbbr, #{taxClass} taxClass, taxStartDate, interestIncome, /*利息收入*/ dividendIncome, /*红利收入*/ difbetIncome, /*价差收入*/ (interestIncome + dividendIncome + difbetIncome) as appreciationTax, constructionTax, educationTax, placeeducationTax, waterTrafficTax, (constructionTax + educationTax + placeeducationTax + waterTrafficTax) as additionalTax, (interestIncome + dividendIncome + difbetIncome + constructionTax + educationTax + placeeducationTax + waterTrafficTax) taxTotal, /*税费总额*/ CONCAT_WS( '', DATE_FORMAT(#{payment1},'%Y'), '年', truncate((DATE_FORMAT(#{payment1},'%m')+2)/3,0), '季度销项税金结转金额:', cast((interestIncome + dividendIncome + difbetIncome + constructionTax + educationTax + placeeducationTax + waterTrafficTax) as decimal(12,4))) remark from (select b.PORTFOLIO_ID, /*组合*/ c.PORTFOLIO_NAME, /*组合名称*/ c.profit_Type profitType, a.FINPROD_ID, a.FINPROD_ABBR, a.FINPROD_MARKET_ID, (select DATE_FORMAT(IFNULL(max(tpd.mdate + 1),a.vdate), '%Y-%m-%d ') from TRD_PRODUCT_DEAL tpd left join BOK_DEAL_ACCOUNTING bda on tpd.trade_id = bda.busi_no where 1 = 1 and tpd.busi_type = #{BUSI_TYPE_16} and IFNULL(tpd.TRADE_STATUS,'01') = #{TRADE_STATUS_01} and tpd.mdate <= #{payment1} and tpd.finprod_id = a.finprod_id and not exists ( select 1 from TRD_PRODUCT_DEAL a1 where a1.p_trade_id = tpd.trade_id and a1.busi_type = tpd.busi_type and a1.TRADE_STATUS =#{TRADE_STATUS_03} ) ) as taxStartDate, IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0102} and bba.chl_id is null), 0) as interestIncome, /*利息收入*/ IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0202} and bba.chl_id is null), 0) as dividendIncome, /*红利收入*/ IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{TAX0302} and bba.chl_id is null), 0) as difbetIncome, /*价差收入*/ IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0102} and bba.chl_id is null), 0) as constructionTax, IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0202} and bba.chl_id is null), 0) as educationTax, IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0302} and bba.chl_id is null), 0) as placeeducationTax, IFNULL((select bba.TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE bba where bba.FINPROD_ID = (case when c.profit_Type = #{profitType_SY} then b.portfolio_id else b.finprod_id end ) and bba.CDATE = #{payment1} and bba.FEE_TYPE = #{ALT0402} and bba.chl_id is null), 0) as waterTrafficTax from FIN_PRODUCT a inner join FIN_PRODUCT_ADD b on a.FINPROD_ID = b.FINPROD_ID inner join PTL_PORTFOLIO c on b.portfolio_id = c.portfolio_id where 1 = 1 and a.FINPROD_TYPE2 = #{FINPROD_TYPE_F16}
and not exists ( select 1 from TRD_PRODUCT_DEAL b1 left join TRD_PRODUCT_DEAL c1 on b1.trade_id = c1.p_trade_id where b1.busi_type = #{BUSI_TYPE_16} and b1.FINPROD_ID = a.FINPROD_ID and b1.mdate = #{payment1} and c1.p_trade_id is null and b1.TRADE_STATUS =#{TRADE_STATUS_01} )
and b.portfolio_id in
#{item}
) zz where IFNULL(interestIncome + dividendIncome + difbetIncome,0) != 0 and PORTFOLIO_ID not in ( select lastDeal.portfolioId from (SELECT tpa.portfolio_id portfolioId, prd.finprod_id finprodId, max(TPD.SETTLE_DATE) payTaxVDate FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{BUSI_TYPE_16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.TRADE_STATUS = #{tradeStatus}
and TPD.PS = #{taxidenType}
group by TPD.PS, tpa.portfolio_id, ptl.PORTFOLIO_NAME, prd.finprod_id, prd.FINPROD_ABBR, tpd.ccy, TPD.TRADE_STATUS order by payTaxVDate,portfolioId desc) lastDeal where lastDeal.payTaxVDate >= #{payment1})

select bbs.BOOKSET_ID as booksetId,bbs.BOOKSET_NAME booksetName from BOK_BOOKSET bbs left join BOK_BOOKSET_DATE BBD on BBD.BOOKSET_ID = bbs.BOOKSET_ID where 1=1
AND BBD.BOOKSET_ID IN
#{booksetId}
and BBD.BOOKSET_DATE > STR_TO_DATE(#{payment2}, '%Y-%m-%d ')
and BBD.BOOKSET_DATE < STR_TO_DATE(#{payment1}, '%Y-%m-%d ') +1
and (BBD.BOOKSET_ID IN ( select FINPROD_ID from FIN_PRODUCT_ADD where PORTFOLIO_ID in
#{item}
) or BBD.BOOKSET_ID IN
#{item}
)

SELECT TPD.PS taxidenType, /*类型*/ tpa.portfolio_id portfolioId,/*组合代码*/ ptl.PORTFOLIO_NAME portfolioName, /*组合名称*/ prd.finprod_id finprodId, prd.FINPROD_ABBR finprodAbbr, tpd.ccy ccy,/*币种*/ DATE_FORMAT(max(TPD.SETTLE_DATE), '%Y-%m-%d ') payTaxVDate, TPD.TRADE_STATUS tradeStatus FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join fin_product prd1 on tpd.chl_id = prd1.finprod_id left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{BUSI_TYPE_16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.TRADE_STATUS = #{tradeStatus}
and prd1.finprod_market_id = #{channelId}
and tpa.portfolio_id in
#{item}
and TPD.PS = #{taxidenType}
group by TPD.PS, tpa.portfolio_id, ptl.PORTFOLIO_NAME, prd.finprod_id, prd.FINPROD_ABBR, tpd.ccy, TPD.TRADE_STATUS order by payTaxVDate,portfolioId desc

select distinct a.* from ( select case when bok.acct_subject_type = #{FINPROD_TYPE_F18} then ptl.portfolio_id when bok.acct_subject_type = #{FINPROD_TYPE_F16} then ad.portfolio_id else null end id, case when bok.acct_subject_type = #{FINPROD_TYPE_F18} then ptl.portfolio_name when bok.acct_subject_type = #{FINPROD_TYPE_F16} then (select ptl1.portfolio_name from ptl_portfolio ptl1 where ad.portfolio_id = ptl1.portfolio_id) else null end text from bok_position_prdfee fee left join bok_bookset bok on fee.finprod_id = bok.acct_subject_id left join fin_product fin on fee.chl_id = fin.finprod_id left join ptl_portfolio ptl on ptl.portfolio_id = fee.finprod_id left join fin_product_add ad on fee.finprod_id = ad.finprod_id where 1 = 1 and fee.cdate = STR_TO_DATE(#{payTaxMDate},'%Y-%m-%d') and fin.finprod_market_id = #{channelId} and fee.tdy_unpaid_intincexp != 0 and fee.fee_type in (#{TAX0302}, #{TAX0202}, #{TAX0102}, #{ALT0102}, #{ALT0202}, #{ALT0302}, #{ALT0402})
and (ad.portfolio_id in
#{item}
or ptl.portfolio_id in
#{item}
)
) a where id is not null and text is not null
